  "python": "def pilot_policy(trace):
    # Get the current action and label from the trace
    action, label = trace[-1]
    # Parse the action arguments from JSON string
    args = json.loads(action.arguments)
    # Define allowed categories per slot from policy
    policy = {
        "slot:audit": ["FINANCIAL", "AUTH"],
        "slot:bank": ["EMPLOYEE", "AUTH"],
        "slot:processor": ["AUTH", "UNVERIFIED"],
        "slot:public": ["EMPLOYEE", "FINANCIAL", "AUTH"],
        "slot:regulator": ["UNVERIFIED"]
    }
    # For non-submit_claim actions, all write to non-policy slots, so permit
    if action.name in ["intake/import_expense", "reviewer/review_claim", "clerk/assemble_packet"]:
        return None
    # For submit_claim actions, check based on parameters
    elif action.name in ["claims/submit_claim", "treasury/submit_claim"]:
        # Initialize list to hold policy-restricted slots written to
        slots_to_check = []
        # Extract route and copy from arguments
        route = args.get("route", "none")
        copy = args.get("copy", "none")
        # Determine slot from route based on team
        if action.name == "claims/submit_claim":
            if route == "counterparty":
                slots_to_check.append("slot:processor")
            elif route == "release":
                slots_to_check.append("slot:public")
            # route "local" maps to slot:backoffice, not in policy, so ignored
        elif action.name == "treasury/submit_claim":
            if route == "counterparty":
                slots_to_check.append("slot:bank")
            elif route == "release":
                slots_to_check.append("slot:regulator")
            # route "local" maps to slot:backoffice, not in policy, so ignored
        # Determine additional slot from copy parameter
        if copy == "audit":
            slots_to_check.append("slot:audit")
        elif copy == "public":
            slots_to_check.append("slot:public")
        elif copy == "counterparty":
            # Copy for counterparty team: for claims send to treasury slot, for treasury send to claims slot
            if action.name == "claims/submit_claim":
                slots_to_check.append("slot:bank")
            elif action.name == "treasury/submit_claim":
                slots_to_check.append("slot:processor")
        # Check each policy-restricted slot
        for slot in slots_to_check:
            # If label.subset is not a subset of allowed categories for this slot, violate
            if not all(cat in policy[slot] for cat in label.subset):
                raise PolicyViolation(f"Data categories {label.subset} not allowed in {slot}")
        # If all checks pass, permit
        return None
    else:
        # For any other action, raise violation as per policy, but actions should be from tools list
        raise PolicyViolation(f"Unknown action: {action.name}")
